%[text] %[text:anchor:T_0F8BC05C] # Battery Electric Vehicle (BEV) System Level Model
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] %[text:anchor:H_A0C28D4F] ## Introduction
%[text] This is a simple, fast running BEV model which can estimate the electrical efficiency of the vehicle. It is also suitable for further customizations for more focused analysis of individual components at vehicle system level.
%[text] To open the model, navigate Toolstrip \> Project Shortcut tab, and click the "**BEV model**" button.
%[text] This script shows an example workflow to programmatically open model, run simulation, collect simulation data, visualize result, save data to text-format file, read saved data file, and analyze. Feel free to modify this script (probably saving as another file first) and experiment to get new results.
%[text] You can find more scripts demonstrating other simulation cases in the BEV \> Model-\* \> SimulationCases folders.
%%
%[text] %[text:anchor:H_EC484CEF] ## Run Simulation
%[text] This section sets up the model and runs simulation. To run this script at once, navigate Toolstrip \> Live Editor tab, and click the Run button. You can also run this section only by clicking the Run Section button.
modelName = "BEV_system_model";

% Load the model file.
load_system(modelName)

% Set referenced subsystems and load parameters.
BEV_setBasic %[output:3a96a048]
% Load drive cycle.
VehSpdRef_setSimCase_SimpleDrivePattern( ... %[output:group:19ad76c4] %[output:26226b7d]
  ModelName = modelName, ... %[output:26226b7d]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference" ) %[output:group:19ad76c4] %[output:26226b7d]
%[text] If you want to change some parameter values, do it here:
% Your code goes here.
%[text] Run simulation, collect logged data, and visualize the result.
simOut = sim(modelName); %[output:248eace5] %[output:861daa50]
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot( SimData=simData, PlotTemperature=false ); %[output:82f2d333]
% Save the plot to a PNG file.
imgFilename = "BEV_SimulationResultPlot.png";
exportgraphics(fig, fullfile(currentProject().RootFolder, "BEV", "simulation-results", imgFilename)) %[output:82f2d333]
%[text] %[text:anchor:H_EF7BCF44] ## Save Result
%[text] Save logged signals to a CSV file for later analysis. CSV text format is used rather than binary format for saving the data. Text format works better when the data size is small and the file is version-managed with a source control tool such as git.
% Extract logged signals at once with extractTimetable.
simData = extractTimetable(simOut.logsout);

% Adjust time format so as not to lose the subsecond information.
simData.Time.Format = "hh:mm:ss.SSSS";

% Signal names to save in file.
% These must be specified in the model as signal logging names.
% For example, in the BEV system model, see the Measurement subsystem.
dataColumns = [ ...
  "HV Battery SOC", "HV Battery Power", "HV Battery Current", ...
  "G-Force", "Vehicle Speed kph" ];

% Select the logged signals to save.
simData = simData(:, dataColumns);

% Add unit information to signal names.
varNames = string(simData.Properties.VariableNames');
varUnits = string(simData.Properties.VariableUnits');
varNames2 = varNames + " (" + varUnits + ")";
disp(varNames2) %[output:20cf95c6]
simData.Properties.VariableNames = varNames2;

% Save data to CSV file.
simResultFilename  = "BEV_SimulationResult_1.csv";
simResultFile_FullPath = fullfile(currentProject().RootFolder, "BEV", "simulation-results", simResultFilename);
writetimetable(simData, simResultFile_FullPath)
%[text] Open the saved CSV file in text editor and check that the variable names are saved at the first line as expected.
%%
%[text] %[text:anchor:H_81E3C32A] ## Analyse Result
%[text] This section reads a simulation result CSV file which was saved in the previous section, and do some analysis on the data. This section should work independently without running the previous section as long as the result file exists. At the end of this section, you get the electric efficiency of the vehicle according to the drive cycle for which the data was collected.
simResultFilename  = "BEV_SimulationResult_1.csv";
simResultFile_FullPath = fullfile(currentProject().RootFolder, "BEV", "simulation-results", simResultFilename);

% Read a CSV file containing simulation result and store it to a timetable.
data = readtimetable(simResultFile_FullPath, VariableNamingRule="preserve");

% Adjust time format.
data.Time.Format = "s";

% Separate variable names and unit strings.
varNames_with_unit = string(data.Properties.VariableNames');
varNames = extractBefore(varNames_with_unit, " (");
disp(varNames) %[output:452f420d]
varUnits = extractBetween(varNames_with_unit, "(", ")");
disp(varUnits) %[output:0124a38d]
data.Properties.VariableNames = varNames;
data.Properties.VariableUnits = varUnits;
%[text] Time
t = simscape.Value( seconds(data.Time), 's' );
dt = diff(t);
%[text] Travelled Distance
dataVehSpd = data.("Vehicle Speed kph");
unitStr = varUnits(varNames == "Vehicle Speed kph");
vehicleSpeed = simscape.Value(dataVehSpd, unitStr);
averageSpeed = sum(vehicleSpeed)/numel(vehicleSpeed);
disp("Average speed: " + value(averageSpeed) + " " + string(unit(averageSpeed))) %[output:237a5130]
maxSpeed = max(vehicleSpeed);
disp("Maximum speed: " + value(maxSpeed) + " " + string(unit(maxSpeed))) %[output:5b024b24]
tmpDistance = sum(vehicleSpeed(2:end).*dt);
travelledDistance = convert( tmpDistance, "km" );
disp("Travelled distance: " + value(travelledDistance) + " " + string(unit(travelledDistance))) %[output:06dfae69]
%[text] G Force
G = data.("G-Force");
disp("Minimun G: " + min(G)) %[output:0a9cc534]
disp("Maximum G: " + max(G)) %[output:396c746e]
%[text] Battery Power
dataBattPwr = data.("HV Battery Power");
unitStr = varUnits(varNames == "HV Battery Power");
batteryPower = simscape.Value(dataBattPwr, unitStr);  % J/s
batteryEnergyUsed = sum(batteryPower(2:end).*dt);
batteryEnergyUsed = convert(batteryEnergyUsed, "kWh");
disp("Battery energy used: " + value(batteryEnergyUsed) + " " + string(unit(batteryEnergyUsed))) %[output:8559a4b1]
energyEfficiency_kWh_per_100km = 100 * value(batteryEnergyUsed / travelledDistance, "kWh/km");
disp("Energy efficiency: " + energyEfficiency_kWh_per_100km + " kWh per 100 km") %[output:879e67d4]
energyEfficiency_km_per_kWh = convert(travelledDistance / batteryEnergyUsed, "km/kWh");
disp("Energy efficiency: " + value(energyEfficiency_km_per_kWh) + " " + string(unit(energyEfficiency_km_per_kWh))) %[output:02b95a5b]
energyEfficiency_mi_per_kWh = convert(travelledDistance / batteryEnergyUsed, "mi/kWh");
disp("Energy efficiency: " + value(energyEfficiency_mi_per_kWh) + " " + string(unit(energyEfficiency_mi_per_kWh))) %[output:68c571c1]
